import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote: base premiums", () => {
  it.todo("empty item list → premium 5 G (only the processing fee)");
  it.todo("a sword → base premium 100 G");
  it.todo("an amulet → base premium 60 G");
  it.todo("a staff → base premium 80 G");
  it.todo("a potion → base premium 40 G");
  it.todo("a single rune (component) → base premium 25 G");
  it.todo("a single moonstone (component) → base premium 25 G");
});

describe("MHPCO Claim Office — quote: component blocks of 3 alike", () => {
  it.todo("2 runes → 50 G base premium (no block)");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
});

describe("MHPCO Claim Office — quote: premium modifiers", () => {
  it.todo("a cursed sword adds a 50 % risk surcharge on the item's base premium");
  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
  it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("a cursed sword with enchantment 5 → both surcharges apply");
  it.todo("a customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("a customer with 1 year with MHPCO → no loyalty discount");
  it.todo("every quote carries a 10 % first insurance surcharge on the policy base premium");
  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
  it.todo("a 5 G processing fee is added at the very end of every premium");
});

describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
  it.todo("cursed sword + plain amulet → item surcharge is 50 G (50 % of the cursed item only), 210 G before policy modifiers and fee");
  it.todo("policy-wide modifiers apply to the sum of all item base premiums");
});

describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
});

describe("MHPCO Claim Office — quote: integration examples", () => {
  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
});

describe("MHPCO Claim Office — claim: standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
  it.todo("a claim reports the remaining cap after the payout");
});

describe("MHPCO Claim Office — claim: special clauses", () => {
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
});

describe("MHPCO Claim Office — claim: deductible per damage event", () => {
  it.todo("dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");
});

describe("MHPCO Claim Office — claim: rounding in the MHPCO's favor", () => {
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
});

describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remaining cap 0 G");
});

describe("MHPCO Claim Office — multiple items of the same type", () => {
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a dragon attack damaging both swords → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than the policy covers → error (whole claim rejected)");
});

describe("MHPCO Claim Office — error cases", () => {
  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
  it.todo("claim references a damage entry whose item is not part of the policy → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount -200 → error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads a JSON scenario from stdin and writes {results: [...]} to stdout");
  it.todo("results array has the same length and order as the input steps");
  it.todo("on an invalid scenario → exits with a non-zero status code, writes an error description to stderr and no results to stdout");
});

