export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (itemType: string): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[itemType];

const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item.type), 0);

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge =
    (policyBasePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;

  return Math.ceil(
    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): StepResult[] =>
  scenario.steps.map((step) => {
    if (step.op === "quote") return { premium: quotePremium(step.items) };
    throw new Error(`Unsupported step: ${step.op}`);
  });

