it("damage to a rune (no enchantment or material), damage 200 G → payout 100 G", () => {
  const results = runScenario({
    customer: { yearsWithMHPCO: 0 },
    steps: [
      { op: "quote", items: [{ type: "rune" }] },
      {
        op: "claim",
        policy: 0,
        incident: {
